export const envelope = [48, 20, 15];

export default function build(api) {
  const { size } = api;
  const seatY = 5;

  // Palette resolution from theme with robust fallbacks
  const woodPlanks = api.theme.wood?.planks ?? "minecraft:spruce_planks";
  const woodLog = api.theme.wood?.log ?? "minecraft:spruce_log";
  const woodStripped = api.theme.wood?.stripped ?? "minecraft:stripped_spruce_log";
  const woodStairs = api.theme.wood?.stairs ?? "minecraft:spruce_stairs";
  const woodSlab = api.theme.wood?.slab ?? "minecraft:spruce_slab";
  const woodFence = api.theme.wood?.fence ?? "minecraft:spruce_fence";
  const woodTrapdoor = api.theme.wood?.trapdoor ?? "minecraft:spruce_trapdoor";

  const stonePrimary = api.theme.stone?.primary ?? "minecraft:terracotta";
  const stoneAccent = api.theme.stone?.accent ?? "minecraft:smooth_sandstone";
  const stoneStairs = api.theme.stone?.stairs ?? "minecraft:sandstone_stairs";
  const stoneSlab = api.theme.stone?.slab ?? "minecraft:sandstone_slab";
  const stoneWall = api.theme.stone?.wall ?? "minecraft:sandstone_wall";

  const groundPlinth = api.theme.ground?.plinth ?? stonePrimary;
  const groundPavement = api.theme.ground?.pavement ?? "minecraft:cut_sandstone";
  const groundScree = api.theme.ground?.scree ?? "minecraft:gravel";
  const wallCore = api.theme.wall?.core ?? stonePrimary;
  const wallParapet = api.theme.wall?.parapet ?? stoneWall;

  function getBaseId(blockStr) {
    return blockStr.split("[")[0];
  }

  function logBlock(axis = "y") {
    return `${getBaseId(woodLog)}[axis=${axis}]`;
  }

  function strippedLog(axis = "y") {
    return `${getBaseId(woodStripped)}[axis=${axis}]`;
  }

  function stairBlock(facing = "north", half = "bottom", shape = "straight") {
    return `${getBaseId(woodStairs)}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function stoneStairBlock(facing = "north", half = "bottom", shape = "straight") {
    return `${getBaseId(stoneStairs)}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function slabBlock(type = "bottom") {
    return `${getBaseId(woodSlab)}[type=${type}]`;
  }

  function stoneSlabBlock(type = "bottom") {
    return `${getBaseId(stoneSlab)}[type=${type}]`;
  }

  function trapdoorBlock(facing = "north", half = "bottom", open = false) {
    return `${getBaseId(woodTrapdoor)}[facing=${facing},half=${half},open=${open}]`;
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2]) {
      api.set(x, y, z, block);
    }
  }

  // Banded desert adobe / masonry stratification
  function getMasonry(x, y, z) {
    const layer = (y + Math.floor(x / 3) + Math.floor(z / 3)) % 5;
    if (layer === 0 || layer === 2) return stonePrimary;
    if (layer === 1) return stoneAccent;
    if (layer === 3) return wallCore;
    return groundPlinth;
  }

  // --- 1. CLIFF ABUTMENT FOUNDATIONS (Following Ground) ---
  function buildAbutmentGround(minX, maxX, minZ, maxZ) {
    for (let x = minX; x <= maxX; x++) {
      for (let z = minZ; z <= maxZ; z++) {
        const h = api.heightAt(x, z);
        const gy = Math.max(0, Math.min(18, Math.round(seatY + h)));

        // Solid downward foundation skirt to terrain
        for (let y = gy; y <= seatY; y++) {
          setBlock(x, y, z, getMasonry(x, y, z));
        }

        // If ground rises above seat plane, build upward to seat with the hillside
        if (gy > seatY) {
          for (let y = seatY + 1; y <= gy; y++) {
            // Keep doorways and bridge corridor clear
            if (z === 7 && y <= 9) continue;
            if (x >= 2 && x <= 5 && z >= 5 && z <= 9 && y <= 10) continue;
            if (x >= 42 && x <= 45 && z >= 5 && z <= 9 && y <= 10) continue;
            setBlock(x, y, z, getMasonry(x, y, z));
          }
        }
      }
    }
  }

  buildAbutmentGround(0, 8, 2, 12);
  buildAbutmentGround(39, 47, 2, 12);

  // --- 2. WEST PUEBLO CLIFF STATION (X: 0 to 8, Z: 2 to 12) ---
  // Sub-platform floors
  for (let x = 0; x <= 8; x++) {
    for (let z = 2; z <= 12; z++) {
      setBlock(x, 6, z, z === 7 ? groundPavement : getMasonry(x, 6, z));
    }
  }

  // West pueblo guardhouse walls
  for (let y = 7; y <= 10; y++) {
    for (let z = 3; z <= 11; z++) {
      setBlock(1, y, z, getMasonry(1, y, z)); // Back wall
      // Front wall facing bridge
      if (z === 7 && y <= 9) {
        // Doorway
      } else if ((z === 4 || z === 10) && y === 8) {
        setBlock(6, y, z, stoneWall); // Window slit
      } else {
        setBlock(6, y, z, getMasonry(6, y, z));
      }
    }
    for (let x = 2; x <= 5; x++) {
      if (x === 3 && y === 8) {
        setBlock(x, y, 3, stoneWall);
        setBlock(x, y, 11, stoneWall);
      } else {
        setBlock(x, y, 3, getMasonry(x, y, 3));
        setBlock(x, y, 11, getMasonry(x, y, 11));
      }
    }
  }

  // Doorway timber framing
  setBlock(6, 7, 6, logBlock("y"));
  setBlock(6, 8, 6, logBlock("y"));
  setBlock(6, 7, 8, logBlock("y"));
  setBlock(6, 8, 8, logBlock("y"));
  setBlock(6, 10, 7, logBlock("z"));

  // Pueblo flat roof and vigas (Y = 11)
  for (let x = 1; x <= 6; x++) {
    for (let z = 3; z <= 11; z++) {
      setBlock(x, 11, z, stonePrimary);
    }
  }
  // Protruding timber vigas (log ends sticking through adobe)
  setBlock(7, 11, 4, logBlock("x"));
  setBlock(7, 11, 6, logBlock("x"));
  setBlock(7, 11, 8, logBlock("x"));
  setBlock(7, 11, 10, logBlock("x"));
  setBlock(2, 11, 2, logBlock("z"));
  setBlock(4, 11, 2, logBlock("z"));
  setBlock(2, 11, 12, logBlock("z"));
  setBlock(4, 11, 12, logBlock("z"));

  // Roof terrace walk and parapets (Y = 12, 13)
  for (let x = 1; x <= 6; x++) {
    for (let z = 3; z <= 11; z++) {
      setBlock(x, 12, z, groundPavement);
    }
  }
  for (let z = 3; z <= 11; z++) {
    setBlock(1, 13, z, z % 2 === 0 ? wallParapet : stonePrimary);
    setBlock(6, 13, z, z % 2 === 0 ? wallParapet : stonePrimary);
  }
  for (let x = 2; x <= 5; x++) {
    setBlock(x, 13, 3, x % 2 === 0 ? wallParapet : stonePrimary);
    setBlock(x, 13, 11, x % 2 === 0 ? wallParapet : stonePrimary);
  }

  // Interior access ladder
  for (let y = 7; y <= 11; y++) {
    setBlock(2, y, 4, "minecraft:ladder[facing=south]");
  }

  // West Deadmen Cable Windlasses (Anchorage turnstiles in rock)
  setBlock(2, 7, 5, logBlock("z"));
  setBlock(2, 7, 9, logBlock("z"));
  setBlock(1, 7, 5, "minecraft:chain[axis=x]");
  setBlock(1, 7, 9, "minecraft:chain[axis=x]");
  setBlock(2, 8, 5, "minecraft:chain[axis=y]");
  setBlock(2, 8, 9, "minecraft:chain[axis=y]");

  // --- 3. EAST PUEBLO CLIFF STATION (X: 39 to 47, Z: 2 to 12) ---
  // Sub-platform floors
  for (let x = 39; x <= 47; x++) {
    for (let z = 2; z <= 12; z++) {
      setBlock(x, 6, z, z === 7 ? groundPavement : getMasonry(x, 6, z));
    }
  }

  // East pueblo guardhouse walls
  for (let y = 7; y <= 10; y++) {
    for (let z = 3; z <= 11; z++) {
      setBlock(46, y, z, getMasonry(46, y, z)); // Back wall
      // Front wall facing bridge
      if (z === 7 && y <= 9) {
        // Doorway
      } else if ((z === 4 || z === 10) && y === 8) {
        setBlock(41, y, z, stoneWall);
      } else {
        setBlock(41, y, z, getMasonry(41, y, z));
      }
    }
    for (let x = 42; x <= 45; x++) {
      if (x === 44 && y === 8) {
        setBlock(x, y, 3, stoneWall);
        setBlock(x, y, 11, stoneWall);
      } else {
        setBlock(x, y, 3, getMasonry(x, y, 3));
        setBlock(x, y, 11, getMasonry(x, y, 11));
      }
    }
  }

  // Doorway timber framing
  setBlock(41, 7, 6, logBlock("y"));
  setBlock(41, 8, 6, logBlock("y"));
  setBlock(41, 7, 8, logBlock("y"));
  setBlock(41, 8, 8, logBlock("y"));
  setBlock(41, 10, 7, logBlock("z"));

  // Pueblo flat roof and vigas (Y = 11)
  for (let x = 41; x <= 46; x++) {
    for (let z = 3; z <= 11; z++) {
      setBlock(x, 11, z, stonePrimary);
    }
  }
  setBlock(40, 11, 4, logBlock("x"));
  setBlock(40, 11, 6, logBlock("x"));
  setBlock(40, 11, 8, logBlock("x"));
  setBlock(40, 11, 10, logBlock("x"));
  setBlock(43, 11, 2, logBlock("z"));
  setBlock(45, 11, 2, logBlock("z"));
  setBlock(43, 11, 12, logBlock("z"));
  setBlock(45, 11, 12, logBlock("z"));

  // Roof terrace walk and parapets (Y = 12, 13)
  for (let x = 41; x <= 46; x++) {
    for (let z = 3; z <= 11; z++) {
      setBlock(x, 12, z, groundPavement);
    }
  }
  for (let z = 3; z <= 11; z++) {
    setBlock(41, 13, z, z % 2 === 0 ? wallParapet : stonePrimary);
    setBlock(46, 13, z, z % 2 === 0 ? wallParapet : stonePrimary);
  }
  for (let x = 42; x <= 45; x++) {
    setBlock(x, 13, 3, x % 2 === 0 ? wallParapet : stonePrimary);
    setBlock(x, 13, 11, x % 2 === 0 ? wallParapet : stonePrimary);
  }

  // Interior access ladder
  for (let y = 7; y <= 11; y++) {
    setBlock(45, y, 10, "minecraft:ladder[facing=north]");
  }

  // East Deadmen Cable Windlasses
  setBlock(45, 7, 5, logBlock("z"));
  setBlock(45, 7, 9, logBlock("z"));
  setBlock(46, 7, 5, "minecraft:chain[axis=x]");
  setBlock(46, 7, 9, "minecraft:chain[axis=x]");
  setBlock(45, 8, 5, "minecraft:chain[axis=y]");
  setBlock(45, 8, 9, "minecraft:chain[axis=y]");

  // --- 4. TIMBER A-FRAME GALLOWS PYLONS (X: 8 & 39) ---
  function buildGallowsPylon(px, approachDir) {
    // Heavy upright timber masts
    for (let y = 6; y <= 16; y++) {
      setBlock(px, y, 5, strippedLog("y"));
      setBlock(px, y, 9, strippedLog("y"));
    }

    // Outer support buttress posts
    for (let y = 6; y <= 9; y++) {
      setBlock(px, y, 4, logBlock("y"));
      setBlock(px, y, 10, logBlock("y"));
    }

    // Base footing plinths
    setBlock(px, 6, 4, stoneStairBlock("south", "bottom"));
    setBlock(px, 6, 10, stoneStairBlock("north", "bottom"));
    setBlock(px + approachDir, 6, 5, stoneStairBlock(approachDir > 0 ? "west" : "east", "bottom"));
    setBlock(px + approachDir, 6, 9, stoneStairBlock(approachDir > 0 ? "west" : "east", "bottom"));

    // Lower portal arch header
    for (let z = 5; z <= 9; z++) {
      setBlock(px, 10, z, logBlock("z"));
    }
    setBlock(px, 9, 6, stairBlock("south", "top"));
    setBlock(px, 9, 8, stairBlock("north", "top"));
    setBlock(px, 9, 7, "minecraft:lantern[hanging=true]");

    // Mid cross tie
    for (let z = 5; z <= 9; z++) {
      setBlock(px, 13, z, strippedLog("z"));
    }

    // Crown mast beam
    for (let z = 4; z <= 10; z++) {
      setBlock(px, 16, z, logBlock("z"));
    }
    // Saddle caps for suspension cables
    setBlock(px, 17, 5, slabBlock("bottom"));
    setBlock(px, 17, 9, slabBlock("bottom"));

    // A-frame diagonal timber back-braces
    const bx = px + approachDir;
    for (let y = 7; y <= 11; y++) {
      setBlock(bx, y, 5, strippedLog("y"));
      setBlock(bx, y, 9, strippedLog("y"));
    }
    setBlock(bx, 12, 5, stairBlock(approachDir > 0 ? "west" : "east", "top"));
    setBlock(bx, 12, 9, stairBlock(approachDir > 0 ? "west" : "east", "top"));
  }

  buildGallowsPylon(8, -1);
  buildGallowsPylon(39, 1);

  // --- 5. CANYON CATWALK & SAGGING SUSPENSION BRIDGE (X: 8 to 39) ---
  function getDeckLevel(x) {
    if (x <= 9 || x >= 38) return 7;
    if (x <= 14 || x >= 33) return 6;
    return 5;
  }

  // Smooth stepping Catwalk deck
  for (let x = 8; x <= 39; x++) {
    const curY = getDeckLevel(x);

    // Crossjoist needle beams on alternating columns
    if (x % 2 === 0 || x === 39) {
      for (let z = 5; z <= 9; z++) {
        setBlock(x, curY - 1, z, strippedLog("z"));
      }
    } else {
      setBlock(x, curY - 1, 6, strippedLog("x"));
      setBlock(x, curY - 1, 8, strippedLog("x"));
    }

    // Catwalk floor blocks & stairs for seamless transition
    if (x === 10) {
      setBlock(x, 6, 6, stairBlock("west", "bottom"));
      setBlock(x, 6, 7, stairBlock("west", "bottom"));
      setBlock(x, 6, 8, stairBlock("west", "bottom"));
    } else if (x === 15) {
      setBlock(x, 5, 6, stairBlock("west", "bottom"));
      setBlock(x, 5, 7, stairBlock("west", "bottom"));
      setBlock(x, 5, 8, stairBlock("west", "bottom"));
    } else if (x === 32) {
      setBlock(x, 5, 6, stairBlock("east", "bottom"));
      setBlock(x, 5, 7, stairBlock("east", "bottom"));
      setBlock(x, 5, 8, stairBlock("east", "bottom"));
    } else if (x === 37) {
      setBlock(x, 6, 6, stairBlock("east", "bottom"));
      setBlock(x, 6, 7, stairBlock("east", "bottom"));
      setBlock(x, 6, 8, stairBlock("east", "bottom"));
    } else {
      for (let z = 6; z <= 8; z++) {
        const prng = api.random();
        if (prng < 0.7) {
          setBlock(x, curY, z, woodPlanks);
        } else if (prng < 0.88) {
          setBlock(x, curY, z, slabBlock("top"));
        } else {
          setBlock(x, curY, z, trapdoorBlock("north", "bottom", false));
        }
      }
    }

    // Continuous handrail ropes along bridge edges
    setBlock(x, curY + 1, 6, woodFence);
    setBlock(x, curY + 1, 8, woodFence);
  }

  // --- 6. SUSPENSION CABLES & VERTICAL HANGER ROPES ---
  const midX = 23.5;
  const halfSpan = 15.5;

  for (let x = 8; x <= 39; x++) {
    const t = (x - midX) / halfSpan;
    const cableY = Math.round(9.0 + 7.0 * t * t);
    const deckY = getDeckLevel(x);

    // Main suspension cable at Z = 5 and Z = 9
    setBlock(x, cableY, 5, woodFence);
    setBlock(x, cableY, 9, woodFence);

    // Vertical suspension hanger ropes linking overhead cable down to needle beams
    if (x % 2 === 0 || x === 39) {
      for (let y = deckY; y < cableY; y++) {
        setBlock(x, y, 5, "minecraft:chain[axis=y]");
        setBlock(x, y, 9, "minecraft:chain[axis=y]");
      }
    }
  }

  // West Backstay Anchors (Pylon top at X=8, Y=16 down to Deadman at X=2, Y=7)
  const westBackstays = [
    [2, 8], [3, 9], [3, 10], [4, 11], [5, 12], [6, 13], [6, 14], [7, 15]
  ];
  for (const [bx, by] of westBackstays) {
    setBlock(bx, by, 5, woodFence);
    setBlock(bx, by, 9, woodFence);
  }

  // East Backstay Anchors (Pylon top at X=39, Y=16 down to Deadman at X=45, Y=7)
  const eastBackstays = [
    [45, 8], [44, 9], [44, 10], [43, 11], [42, 12], [41, 13], [41, 14], [40, 15]
  ];
  for (const [bx, by] of eastBackstays) {
    setBlock(bx, by, 5, woodFence);
    setBlock(bx, by, 9, woodFence);
  }

  // Cantilever cliff brackets under bridge landings
  for (let z = 5; z <= 9; z++) {
    setBlock(9, 5, z, stoneStairBlock("west", "top"));
    setBlock(9, 4, z, getMasonry(9, 4, z));
    setBlock(38, 5, z, stoneStairBlock("east", "top"));
    setBlock(38, 4, z, getMasonry(38, 4, z));
  }

  // Wind stabilizer sway guy-wires underneath the bridge
  setBlock(8, 4, 3, woodFence);
  setBlock(9, 4, 4, woodFence);
  setBlock(10, 4, 5, woodFence);
  setBlock(8, 4, 11, woodFence);
  setBlock(9, 4, 10, woodFence);
  setBlock(10, 4, 9, woodFence);

  setBlock(39, 4, 3, woodFence);
  setBlock(38, 4, 4, woodFence);
  setBlock(37, 4, 5, woodFence);
  setBlock(39, 4, 11, woodFence);
  setBlock(38, 4, 10, woodFence);
  setBlock(37, 4, 9, woodFence);

  return {
    name: "canyon_rope_bridge",
    seatY,
    anchors: {
      front: [24, 6, 0],
      west_approach: [0, 6, 7],
      east_approach: [47, 6, 7],
      span_mid: [24, 5, 7],
      west_tower: [8, 16, 7],
      east_tower: [39, 16, 7]
    },
    interiors: [
      {
        min: [2, 7, 5],
        max: [5, 10, 9],
        kind: "quarters"
      },
      {
        min: [42, 7, 5],
        max: [45, 10, 9],
        kind: "quarters"
      }
    ]
  };
}

sunken_kiva.source:
export const envelope = [11, 14, 11];

export default function build(api) {
  const { size, theme, instance } = api;
  const rng = () => api.random();
  const inst = instance.index % 4;
  const seatY = 4;

  const cx = 5;
  const cz = 5;

  // Resolve palette from theme with reliable ancient Pueblo fallbacks
  const stonePrimary = theme.stone?.primary || theme.ground?.plinth || "minecraft:cut_sandstone";
  const stoneAccent = theme.stone?.accent || theme.ground?.pavement || stonePrimary;
  const stoneSlab = theme.stone?.slab || theme.ground?.slab || "minecraft:sandstone_slab";
  const stoneWall = theme.stone?.wall || theme.wall?.parapet || "minecraft:sandstone_wall";

  const groundPavement = theme.ground?.pavement || stonePrimary;
  const groundPlinth = theme.ground?.plinth || stonePrimary;
  const groundScree = theme.ground?.scree || stoneAccent;

  const woodLog = theme.wood?.log || "minecraft:oak_log";
  const woodStripped = theme.wood?.stripped || woodLog;
  const woodPlanks = theme.wood?.planks || "minecraft:oak_planks";
  const woodFence = theme.wood?.fence || "minecraft:oak_fence";
  const woodSlab = theme.wood?.slab || "minecraft:oak_slab";
  const woodTrapdoor = theme.wood?.trapdoor || "minecraft:oak_trapdoor";

  const roofSolid = theme.roof?.solid || stonePrimary;
  const roofSlab = theme.roof?.slab || stoneSlab;
  const wallParapet = theme.wall?.parapet || stoneWall;
  const wallMerlon = theme.wall?.merlon || stonePrimary;

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2] && block) {
      api.set(x, y, z, block);
    }
  }

  function setLogAxis(logStr, axis) {
    if (!logStr) return logStr;
    if (logStr.includes("axis=")) {
      return logStr.replace(/axis=[xyz]/, `axis=${axis}`);
    }
    if (logStr.includes("[")) {
      return logStr.replace("]", `,axis=${axis}]`);
    }
    return `${logStr}[axis=${axis}]`;
  }

  function setSlab(slabStr, type) {
    if (!slabStr) return slabStr;
    if (slabStr.includes("type=")) {
      return slabStr.replace(/type=[a-z]+/, `type=${type}`);
    }
    if (slabStr.includes("[")) {
      return slabStr.replace("]", `,type=${type}]`);
    }
    return `${slabStr}[type=${type}]`;
  }

  // Instance specific geometry variations
  const radiusProfiles = [
    { rOuter: 4.8, rInner: 3.6, pilasters: 6, vigaDir: "z", hatchSize: 2, ladderH: 13 },
    { rOuter: 4.5, rInner: 3.3, pilasters: 4, vigaDir: "x", hatchSize: 1, ladderH: 12 },
    { rOuter: 4.9, rInner: 3.7, pilasters: 6, vigaDir: "cribbed", hatchSize: 2, ladderH: 13 },
    { rOuter: 4.6, rInner: 3.4, pilasters: 8, vigaDir: "cross", hatchSize: 1, ladderH: 12 },
  ];
  const cfg = radiusProfiles[inst];
  const rOuter = cfg.rOuter;
  const rInner = cfg.rInner;

  // 1. Foundation & Subterranean Skirt (conforming to real terrain)
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist <= rOuter + 0.35) {
        const h = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(size[1] - 1, seatY + h));
        const minY = Math.min(groundY, seatY);
        for (let y = minY; y <= seatY; y++) {
          const r = rng();
          const block = r < 0.6 ? groundPlinth : r < 0.85 ? stonePrimary : groundPavement;
          setBlock(x, y, z, block);
        }
      }
    }
  }

  // 2. Kiva Flagstone Floor at seatY
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist <= rOuter) {
        let floorBlock = groundPavement;
        const r = rng();
        if (r < 0.5) floorBlock = groundPavement;
        else if (r < 0.8) floorBlock = stonePrimary;
        else floorBlock = groundPlinth;

        if (x === cx && z === cz + 1) {
          floorBlock = stoneAccent; // fire hearth base
        } else if (x === cx && z === cz - 2) {
          floorBlock = groundScree; // sipapu indentation
        }
        setBlock(x, seatY, z, floorBlock);
      }
    }
  }

  // 3. Masonry Outer Drum Wall (y = 5 to 9)
  for (let y = seatY + 1; y <= seatY + 5; y++) {
    for (let x = 0; x < size[0]; x++) {
      for (let z = 0; z < size[2]; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.sqrt(dx * dx + dz * dz);

        let isWall = dist <= rOuter && dist > rInner;
        if (inst === 2 && z >= 8 && Math.abs(dx) <= 1 && y < seatY + 4) {
          // Keyhole southern alcove
          if (z === 9 && dist <= rOuter + 0.5) isWall = true;
          else if (z === 8) isWall = false;
        }

        if (isWall) {
          const r = rng();
          const wallBlock = r < 0.65 ? stonePrimary : r < 0.85 ? stoneAccent : groundPlinth;
          setBlock(x, y, z, wallBlock);
        }
      }
    }
  }

  // 4. Ritual Stone Bench (Banquette) along inside perimeter at y = 5
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist <= rInner && dist > rInner - 0.95) {
        if (!(inst === 2 && z >= 7 && Math.abs(dx) <= 1)) {
          const benchBlock = inst === 1 && rng() < 0.4 ? setSlab(woodSlab, "bottom") : setSlab(stoneSlab, "bottom");
          setBlock(x, seatY + 1, z, benchBlock);
        }
      }
    }
  }

  // 5. Pilasters (Masonry pillars supporting roof vigas)
  const numPilasters = cfg.pilasters;
  for (let i = 0; i < numPilasters; i++) {
    const angle = (i * (360 / numPilasters) + (inst === 1 ? 45 : 0)) * (Math.PI / 180);
    const px = Math.round(cx + (rInner - 0.25) * Math.cos(angle));
    const pz = Math.round(cz + (rInner - 0.25) * Math.sin(angle));
    for (let y = seatY + 1; y <= seatY + 3; y++) {
      setBlock(px, y, pz, stoneAccent);
    }
  }

  // 6. Hearth & Deflector Slab at y = 5
  setBlock(cx, seatY + 1, cz + 2, stoneWall);
  setBlock(cx, seatY + 1, cz + 1, setSlab(stoneSlab, "bottom"));

  // 7. Heavy Timber Roof Beams (Vigas) at y = 8
  const vigaY = seatY + 4;
  if (cfg.vigaDir === "z" || cfg.vigaDir === "cross") {
    for (const bx of [3, 5, 7]) {
      for (let z = 0; z < size[2]; z++) {
        const dx = bx - cx;
        const dz = z - cz;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist <= rOuter || (cfg.vigaDir === "cross" && bx === 5 && (z === 0 || z === 10))) {
          if (!(bx === cx && z === cz)) {
            setBlock(bx, vigaY, z, setLogAxis(woodLog, "z"));
          }
        }
      }
    }
  }
  if (cfg.vigaDir === "x" || cfg.vigaDir === "cross") {
    for (const bz of [3, 5, 7]) {
      for (let x = 0; x < size[0]; x++) {
        const dx = x - cx;
        const dz = bz - cz;
        const dist = Math.sqrt(dx * dx + dz * dz);
        if (dist <= rOuter || (cfg.vigaDir === "cross" && bz === 5 && (x === 0 || x === 10))) {
          if (!(x === cx && bz === cz)) {
            setBlock(x, vigaY, bz, setLogAxis(woodLog, "x"));
          }
        }
      }
    }
  }
  if (cfg.vigaDir === "cribbed") {
    const cribBeams = [
      [3, 2], [4, 2], [7, 2], [8, 3],
      [8, 7], [7, 8], [3, 8], [2, 7],
      [2, 4], [2, 6], [8, 4], [8, 6],
    ];
    for (const [bx, bz] of cribBeams) {
      setBlock(bx, vigaY, bz, setLogAxis(woodStripped, "x"));
    }
  }

  // Latillas / secondary ceiling slats closing roof gaps at y = 8
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist <= rInner) {
        if (!(x === cx && z === cz) && !(cfg.hatchSize === 2 && x === cx + 1 && z === cz)) {
          setBlock(x, vigaY, z, setSlab(woodSlab, "top"));
        }
      }
    }
  }

  // 8. Flat Roof Deck at y = 9
  const deckY = seatY + 5;
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist <= rOuter) {
        const isHatch = (x === cx && z === cz) || (cfg.hatchSize === 2 && x === cx + 1 && z === cz);
        if (!isHatch) {
          const r = rng();
          const deckBlock = r < 0.6 ? roofSolid : r < 0.85 ? groundPavement : woodPlanks;
          setBlock(x, deckY, z, deckBlock);
        }
      }
    }
  }

  // 9. Parapet Rim & Hatch Frame at y = 10
  const rimY = seatY + 6;
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist <= rOuter + 0.25 && dist > rInner) {
        let rimBlock;
        if (inst === 0) {
          rimBlock = wallParapet;
        } else if (inst === 1) {
          rimBlock = setSlab(stoneSlab, "bottom");
        } else if (inst === 2) {
          rimBlock = (x + z) % 2 === 0 ? wallMerlon : setSlab(stoneSlab, "bottom");
        } else {
          rimBlock = rng() < 0.7 ? setSlab(roofSlab, "bottom") : wallParapet;
        }
        setBlock(x, rimY, z, rimBlock);
      }
    }
  }
  setBlock(cx, rimY, cz - 1, woodTrapdoor);
  setBlock(cx, rimY, cz + 1, woodTrapdoor);

  // 10. Central Upright Timber Ladder (Floor to Sky)
  // Support timber behind ladder
  for (let y = seatY; y <= deckY; y++) {
    setBlock(cx, y, cz - 1, setLogAxis(woodStripped, "y"));
  }
  // Ladder rungs facing South
  for (let y = seatY; y <= deckY; y++) {
    setBlock(cx, y, cz, "minecraft:ladder[facing=south]");
  }
  // Protruding ladder stiles (poles) sticking out above the roof
  const ladderTop = cfg.ladderH;
  for (let y = deckY; y <= ladderTop; y++) {
    setBlock(cx - 1, y, cz, woodFence);
    setBlock(cx + 1, y, cz, woodFence);
  }
  if (inst === 0 || inst === 2) {
    setBlock(cx, ladderTop, cz, woodFence);
  }

  return {
    name: "sunken_kiva",
    seatY: 4,
    anchors: {
      front: [5, 4, 0],
      entry: [5, 10, 5],
      hearth: [5, 5, 7],
    },
    interiors: [
      {
        min: [3, 5, 3],
        max: [7, 8, 7],
        kind: "vault",
      },
    ],
  };
}
